use std::collections::HashMap;

fn get_or_insert(map: &mut HashMap<u32, String>, key: u32) -> &String {
    if let Some(v) = map.get(&key) {
        return v;
    }
    map.insert(key, String::new());
    map.get(&key).unwrap()
}

fn main() {
    let mut map = HashMap::new();
    println!("{:?}", get_or_insert(&mut map, 1));
}
```

